/**
 * Selective self-stretching programmes reconstructed from
 * 한림대학교 동탄성심병원 도수치료실 「안면마비 선택적 스트레칭」
 * (https://www.youtube.com/watch?v=Af6RCxwQZiE), narration transcript and frames.
 *
 * All coordinates are ELC (see face.ts): x outward on the affected side,
 * y up, unit = half palpebral width. `pos` is the contact at rest, `move`
 * the displacement at full stretch ([0,0] = fixing), `from` points from the
 * fingertip towards the wrist (where the hand comes from).
 *
 * Accuracy per step (`source`):
 *   frame-grid     – fingertips read on an ELC grid drawn from face landmarks
 *                    on the reference frames (compare-refs)
 *   video-observed – hand placement read from paused video frames + narration
 * Therapist review is still required before clinical use.
 */
import type { MuscleId, Pt } from './face';

export type ContactKind = 'finger' | 'palm' | 'thumb' | 'hook';

export interface Contact {
  /** A = blue, B = orange (by convention A is the fixing hand when there is one). */
  hand: 'A' | 'B';
  kind: ContactKind;
  label: '검지' | '중지' | '약지' | '엄지' | '손바닥';
  pos: Pt;
  move: Pt;
  from: Pt;
  /** Anatomical landmark touched. */
  land: string;
  /** What this contact does. */
  act: string;
  /** Finger placed inside the mouth. */
  intraoral?: boolean;
  /** Which arm the demonstrator uses where the video shows it (the 3D hand model and the clip use the same one). */
  arm?: 'healthy' | 'affected';
}

export interface StretchStep {
  id: string;
  short: string;
  title: string;
  /** Narration of the source video for this step (paraphrased where garbled). */
  narration: string;
  /** Voice cue at the start of the step. */
  cue: string;
  contacts: Contact[];
  muscle: MuscleId;
  eyesClosed?: boolean;
  /**
   * Head motion at full stretch, on top of headStart: yaw + = towards the healthy side, pitch + = chin up (deg).
   * Only where the source video's front camera shows it: the subtitles ask to turn or raise the head in several steps,
   * but the demonstrator's head barely moves (the side and close-up cameras only make it look tilted).
   */
  head?: { yaw?: number; pitch?: number };
  /** Head posture held through the step, turned in with the hands (zyg-minor 8:12: 45° towards the healthy side). */
  headStart?: { yaw?: number; pitch?: number };
  /** Start of the step in the source video (s). */
  videoAt: number;
  source: 'frame-grid' | 'video-observed';
}

export interface StretchProgram {
  id: string;
  muscle: MuscleId;
  steps: StretchStep[];
}

export const HALLYM_VIDEO = 'https://www.youtube.com/watch?v=Af6RCxwQZiE';
export const videoLink = (sec: number) => `${HALLYM_VIDEO}&t=${Math.floor(sec)}`;
export const mmss = (sec: number) => `${Math.floor(sec / 60)}:${String(Math.floor(sec % 60)).padStart(2, '0')}`;

