export const stretchById = (id: string) => STRETCHES.find((s) => s.id === id);

export const isFixed = (c: Contact) => c.move[0] === 0 && c.move[1] === 0;
export const contactAt = (c: Contact, k: number): Pt => [c.pos[0] + c.move[0] * k, c.pos[1] + c.move[1] * k];
